import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to mimic specific ELA properties. The function is constructed
    as a sum of a Rosenbrock-like term, a skewed quadratic term, and a linear term. This combination aims
    to control linearity, quadraticity, skewness, and fitness-distance correlation, resulting in a landscape
    with targeted ELA features.

    Formula:
    f(x) = Rosenbrock(x) + SkewedQuadratic(x) + LinearTerm(x)

    where:
    Rosenbrock(x) = sum(100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2)
    SkewedQuadratic(x) = sum(i * x[i]**2 + x[i]**3), with i indexing from 0 (to introduce skewness)
    LinearTerm(x) = sum(0.01*x)
    """

    def rosenbrock(x):
        return np.sum(100.0 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2) if len(x) > 1 else 0.0

    def skewed_quadratic(x):
        return np.sum(np.arange(len(x)) * x**2 + x**3)

    def linear_term(x):
        return np.sum(0.01 * x)

    return rosenbrock(x) + skewed_quadratic(x) + linear_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a modified Rastrigin-like term,
    a Gaussian kernel, and a linear bias to shape the ELA features. The Gaussian kernel affects the smoothness
    and the correlation between neighbors, while the linear term helps controlling linear ELA features.

    Formula:
    f(x) = ModifiedRastrigin(x) + GaussianKernel(x) + LinearBias(x)

    where:
    ModifiedRastrigin(x) = sum(x^2 - 10 * cos(2*pi*x))+ 20
    GaussianKernel(x) = -exp(-0.5 * ||x - c||^2 / sigma^2), where c = [1, -1] and sigma = 2
    LinearBias(x) = 0.02 * sum(x)
    """

    def modified_rastrigin(x):
        return np.sum(x**2 - 10 * np.cos(2 * np.pi * x)) + 20

    def gaussian_kernel(x):
        c = np.array([1.0, -1.0])  # Center point
        sigma = 2.0  # Standard deviation (bandwidth)
        return -np.exp(-0.5 * np.sum((x - c)**2) / sigma**2)

    def linear_bias(x):
        return 0.02 * np.sum(x)

    return modified_rastrigin(x) + gaussian_kernel(x) + linear_bias(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA characteristics.
    It combines a polynomial term, a logarithmic component and a product of sigmoid functions
    to achieve low linearity/quadraticity and a small skewness.

    Formula:
    f(x) = sum(x^4) + 0.2 * sum(log(abs(x) + 1)) + 0.1 * prod(sigmoid(x))

    where sigmoid(x) = 1 / (1 + exp(-x)) and log is the natural logarithm.
    """

    def sigmoid(x):
        return 1 / (1 + np.exp(-x))

    return np.sum(x**4) + 0.2 * np.sum(np.log(np.abs(x) + 1)) + 0.1 * np.prod(sigmoid(x))

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a Rosenbrock-like term,
    a shifted quadratic term, and a small cubic term to shape the ELA features. The Rosenbrock term introduces ruggedness and epistasis,
    while the quadratic shift controls skewness and the cubic term adjusts nonlinearity.

    Formula:
    f(x) = ModifiedRosenbrock(x) + ShiftedQuadratic(x) + CubicTerm(x)

    where:
    ModifiedRosenbrock(x) = sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0), with a scaling factor

    ShiftedQuadratic(x) = 0.1 * sum((x - shift)^2), where shift = [0.5, -0.5]

    CubicTerm(x) = 0.005 * sum(x^3)
    """

    def modified_rosenbrock(x):
        return 0.05 * np.sum(100.0 * (x[1:] - x[:-1]**2.0)**2.0 + (1 - x[:-1])**2.0) if x.shape[0] > 1 else 0 #Scaled and prevent failure with 1D array

    def shifted_quadratic(x):
        shift = np.array([0.5, -0.5])
        return 0.1 * np.sum((x - shift)**2)

    def cubic_term(x):
      return 0.005 * np.sum(x**3)

    return modified_rosenbrock(x) + shifted_quadratic(x) + cubic_term(x)
